# src/requests/structures.py

from collections import MutableMapping

class CaseInsensitiveDict(MutableMapping):
    """A case-insensitive ``dict``-like object.

    Implements all methods and operations of
    ``collections.MutableMapping`` as well as dict's ``copy()``
    and ``get()``.

    Also comes with a few extra methods, such as caps lock, which
    converts all keys to uppercase.

    Usage is the same as a regular ``dict``:
    >>> d = CaseInsensitiveDict()
    >>> d['Header'] = 'value'
    >>> d['HEADER']
    'value'
    """

    def __init__(self, *args, **kwargs):
        self.store = dict()
        self.update(dict(*args, **kwargs))  # use the ordinary dict to initialize the internal dict

    def __contains__(self, key):
        return key.lower() in self.store

    def __setitem__(self, key, value):
        # Store the key in lowercase to make it case-insensitive
        self.store[key.lower()] = (key, value)

    def __getitem__(self, key):
        # Retrieve the value using the lowercase key
        return self.store[key.lower()][1]

    def __delitem__(self, key):
        # Delete the item using the lowercase key
        del self.store[key.lower()]

    def __iter__(self):
        # Iterate over the keys in the original case
        return iter([k for k, v in self.store.values()])

    def __len__(self):
        # Return the number of items
        return len(self.store)

    def clear(self):
        # Clear all items
        self.store.clear()

    def copy(self):
        # Return a shallow copy of the dictionary
        return CaseInsensitiveDict(self.store)

    def get(self, key, default=None):
        # Retrieve the value with a default value
        return self.store.get(key.lower(), (None, default))[1]

    def setdefault(self, key, default=None):
        # Set the default value if the key is not present
        if key.lower() not in self.store:
            self.store[key.lower()] = (key, default)
        return self.store[key.lower()][1]

    def pop(self, key, default=None):
        # Pop the item with a default value
        if key.lower() in self.store:
            key, value = self.store.pop(key.lower())
            return value
        return default

    def popitem(self):
        # Pop an arbitrary item
        key, value = self.store.popitem()
        return key, value

    def update(self, *args, **kwargs):
        # Update the dictionary with another mapping
        for arg in args:
            if isinstance(arg, Mapping):
                for key, value in arg.items():
                    self.store[key.lower()] = (key, value)
            elif hasattr(arg, 'items'):
                for key, value in arg.items():
                    self.store[key.lower()] = (key, value)
            else:
                for key, value in arg:
                    self.store[key.lower()] = (key, value)
        for key, value in kwargs.items():
            self.store[key.lower()] = (key, value)

